{
  "summary": "Start by constructing a table to filter and calculate the necessary values for the acceptance ratio and totals.",
  "actions": [
    {
      "tool": "construct_table",
      "name": "table.json",
      "schema": {
        "events": {
          "accepted": "INTEGER",
          "attempts": "INTEGER",
          "lane": "TEXT",
          "revision": "INTEGER",
          "state": "TEXT"
        }
      },
      "sql": "SELECT lane, MAX(revision) AS latest_revision, SUM(accepted) AS accepted_total, SUM(attempts) AS attempt_total FROM ledger GROUP BY lane HAVING state = 'active'"
    }
  ],
  "done": false
}
